Define the following a priori probability measures on $\R^N$:
\be\label{eq:prior}
\begin{cases}
\s_{N,R}(dx)&\mbox{uniform on $S^N(R)$}\,;\\
\g_{N,\theta}(dx)&\mbox{centred Gaussian with covariance $\theta \mathbb I$}\,.

\label{th:main}
Assume $\bf P1), P2)$ and let $\r_N, \r^2_N$ be defined as in (\ref{eq:Reg-prior1}), (\ref{eq:Reg-prior2}) and discussion around. Then
\begin{itemize}
\item[i)] $HM_{\s}\xleftrightarrow{LT} HM_{\r}$:
\be\label{eq:mainHM}
A_\r(\theta,\a,\b)=\a \sup_{R>0}\left( \a^{-1}A_{\s}(R,\b) -\frac{R^2}{2\theta}+\log R- r(R) -\frac12(\log\theta-1) \right)\,;
\ee
\be\label{eq:mainHM-dual}
A_{\s}(R,\b)=\a \inf_{\theta>0}\left(\frac{R^2}{2\theta}+\a^{-1}A_\r(\theta,\a,\b) -\log R+ r(R)+\frac12(\log\theta-1)\right)\,.
\ee
\item[ii)] $RBM_{\s\s}\xleftrightarrow{LT} RBM_{\s,\g}$:
\be\label{eq:mainRBM1}
A_{\s,\g}(\theta,R_2,\a,\b)=\a\sup_{R_1>0}\left(\a^{-1}A_{\s\s}(R_1,R_2,\b)-\frac{R_1^2}{2\theta}+\log R_1 -\frac12(\log\theta-1)\right)\,;
\ee
\be\label{eq:mainRBM1-dual}
A_{\s\s}(R_1,R_2,\b)=\a\inf_{\theta>0}\left(\frac{R_1^2}{2\theta}+\a^{-1}A_{\s,\g}(\theta,R_2,\a,\b)-\log R_1+\frac12(\log\theta-1)\right)\,.
\ee
\item[iii)] $RBM_{\s\s}\xleftrightarrow{LT} RBM_{\r^2}$:
\be\label{eq:mainRBM2}
A_{\r^2}(\theta,\a,\b)=\sup_{R_1,R_2>0}\left(A_{\s\s}(R_1,R_2)-\frac{\a R_1^2+(1-\a)R_2^2}{2\theta}+\log(R_1^\a R_2^{1-\a})-\sqrt{\a(1-\a)}r(R_1,R_2)-\frac12(\log\theta-1)\right)\,;
\ee
\be\label{eq:mainRBM2-dual}
A(R_1,R_2)=\inf_{\theta_1,\theta_2>0}\left(\frac{\a R_1^2}{2\theta_1}+\frac{(1-\a)R_2^2}{2\theta_2}+A_{\r^2}(\theta_1,\theta_2,\a,\b)-\log(R_1^\a R_2^{1-\a})+\sqrt{\a(1-\a)}r(R_1,R_2)+\frac12(\log\theta_1^\a\theta_2^{1-\a}-1)\right)\,. 
\ee
\end{itemize}

\label{Th:HM-sfer}
Let $A_{N_1,N_2}$ denote the free energy of $HM_{\s}$. It holds $P$-a.s.
\be\label{eq:AHMsfer}
\lim_{N_1,N_2\to\infty} A_{N_1,N_2} = \a\min_{2q\geq \b(1-\a)\l_+}\left(q R^2 -\frac 12\int\r_{MP}(\l;\a)\log(2q-\b(1-\a)\l) d\l-\log R-\frac12\right)\,.
\ee

\label{Th:Bip-sfer}
Let $A_{N_1,N_2}$ denote the free energy of $RBM_{\s\s}$ and $\a\leq \frac 12$. It holds $P$-a.s.
\begin{eqnarray}
\lim_{N_1,N_2\to\infty} A_{N_1,N_2} &=&\min_{ab\geq \b^2(1-\a)\l_+}\left(\frac{R^2}{2}\left(\a a + (1-\a) b\right) -\frac 1 2 (1-2\a)\log(b)\right. \nonumber \\
 &-&\left.\frac \a2\int\r_{MP}(\l;\a)\log(ab-\b^2(1-\a)\l) d\l-\log R-\frac12\right) \label{eq:Bip-sfer}\,.


\end{eqnarray}

\label{lemma:HM-sfer}
For any $a>\l_+$ there is a $c>0$ such that
\be\label{eq:lemma-HM-sfer}
E[A_{N_1,N_2}(\b,R)1_{\{\|\frac{\Xi\Xi^T}{N_2}\|_{op}>a\}}]=\OOO{e^{-cN_1}}\,. 
\ee

\label{lemma:apriori-bound-HM}
Let $A_{N_1,N_2}$ be the free energy of $HM_{\r}$. There is $f(\l_+,\b)$ continuous and bounded for which
\be\label{eq:ann-bound}
\lim\sup_{N_1,N_2} E[A_{N_1,N_2}]\leq f(\l_+,\b)\,. 
\ee

\label{lemma:apriori-bound-HM}
Let $A_{N_1,N_2}$ be the free energy of $RBM_{\r^2}$. There is $f(\l_+,\b)$ continuous and bounded for which
\be\label{eq:ann-bound}
\lim\sup_{N_1,N_2} E[A_{N_1,N_2}]\leq f(\l_+,\b)\,. 
\ee
